questions.uml_mutation:
class User {
    -String userId
    +getUserId() : String
    -String email
    +getEmail() : String
}

class Group {
    -String groupId
    -String name
}
Group "*" o-- "*" User : members

class Split {
    <<abstract>>
    -double amount
    +getAmount() : double
}
class EqualSplit
class ExactSplit
class PercentSplit {
    -double percent
}
Split <|-- EqualSplit
Split <|-- ExactSplit
Split <|-- PercentSplit

class SplitValidator {
    <<interface>>
    +validate(Expense expense) : boolean
}
class PercentSplitValidator {
    +validate(Expense expense) : boolean
}
class ExactSplitValidator {
    +validate(Expense expense) : boolean
}
SplitValidator <|.. PercentSplitValidator
SplitValidator <|.. ExactSplitValidator
Expense ..> SplitValidator : validated_by

class BalanceSheet {
    -Map balances
    +getNetBalance(User user1, User user2) : double
    +updateBalance(User payer, User owee, double amount)
}

class ExpenseObserver {
    <<interface>>
    +onExpenseAdded(Expense expense)
}
User <|.. ExpenseObserver
Group --> ExpenseObserver : notifies

class ExpenseManager {
    -ExpenseManager instance$
    +getInstance()$ : ExpenseManager
}
ExpenseManager *-- BalanceSheet : orchestrates

class ExpenseManager {
    -ExpenseManager instance$
    +getInstance()$ : ExpenseManager
    +addExpense(ExpenseType type, double amount, String payerId, List splits, String groupId)
}
ExpenseManager *-- BalanceSheet : orchestrates
